package main

import (
	"fmt"
	"sync"
	"time"
)

// Models the exact pattern in updateAddrs (head version):
//   G1 holds mu, spawns G2 without unlocking, then (via defer) tries to
//   Lock mu again in the same goroutine before returning.
// G2 models resetTransportAndUnlock: does a little work, then Unlocks.

var mu sync.Mutex

func spawnedWork(unlockAfter time.Duration, done chan<- struct{}) {
	time.Sleep(unlockAfter) // models "read fields, compute backoff, etc."
	mu.Unlock()
	close(done)
}

func callerFunc() (blockedFor time.Duration) {
	mu.Lock() // like updateAddrs's ac.mu.Lock() at top
	done := make(chan struct{})
	go spawnedWork(50*time.Millisecond, done) // like `go ac.resetTransportAndUnlock()`

	start := time.Now()
	defer func() {
		// like the deferred GracefulClose -> onClose's ac.mu.Lock()
		mu.Lock()
		blockedFor = time.Since(start)
		mu.Unlock()
	}()
	return
}

func main() {
	d := callerFunc()
	fmt.Printf("caller's deferred re-Lock blocked for %v (expected >= ~50ms)\n", d)
	if d < 40*time.Millisecond {
		fmt.Println("UNEXPECTED: did not observe cross-goroutine blocking")
	} else {
		fmt.Println("CONFIRMED: caller blocked on a lock it nominally already held, waiting for the goroutine it just spawned to release it")
	}
}
